    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "type": "object",
    "properties": {
      "request_id": {
        "type": "string",
        "pattern": "^SUB\\d{6}$"
      },
      "subscriber_id": {
        "type": "string",
        "pattern": "^AC\\d{6}$"
      },
      "change_type": {
        "type": "string",
        "enum": ["更换套餐", "暂停服务", "取消订阅"]
      },
      "new_plan": {
        "type": "string",
        "enum": ["基础版", "专业版", "企业版"],
        "oneOf": [
          {
            "if": {
              "properties": {
                "change_type": {
                  "const": "更换套餐"
                }
              },
              "required": ["change_type"]
            },
            "then": {
              "type": "string",
              "enum": ["基础版", "专业版", "企业版"]
            }
          },
          {
            "else": {
              "type": "string",
              "default": null
            }
          }
        ]
      },
      "pause_until": {
        "type": "string",
        "format": "date",
        "oneOf": [
          {
            "if": {
              "properties": {
                "change_type": {
                  "const": "暂停服务"
                }
              },
              "required": ["change_type"]
            },
            "then": {
              "type": "string",
              "format": "date"
            }
          },
          {
            "else": {
              "type": "string",
              "default": null
            }
          }
        ]
      },
      "cancel_reason": {
        "type": "string",
        "oneOf": [
          {
            "if": {
              "properties": {
                "change_type": {
                  "const": "取消订阅"
                }
              },
              "required": ["change_type"]
            },
            "then": {
              "type": "string"
            }
          },
          {
            "else": {
              "type": "string",
              "default": null
            }
          }
        ]
      }
    },
    "required": [
      "request_id",
      "subscriber_id",
      "change_type"
    ],
    "additionalProperties": false
  },
  "data": {
    "request_id": "SUB000023",
    "subscriber_id": "AC000023",
    "change_type": "暂停服务",
    "pause_until": "2026-12-23",
    "new_plan": null,
    "cancel_reason": null
  }
}

